#!/usr/bin/env python3
"""Emit one normalized JSON state snapshot per visible Linux bond."""
import json
import os
import time
from pathlib import Path

COLLECTOR = "linux_bond_state_v1"
SYS_CLASS_NET = Path("/sys/class/net")


def read_text(path):
    return path.read_text(encoding="ascii").strip()


def read_optional(path, conversion=str):
    try:
        return conversion(read_text(path))
    except (FileNotFoundError, OSError, UnicodeError, ValueError):
        return None


def emit(status, observed_at_epoch, boot_id, namespace_inode, **fields):
    event = {
        "event_version": 1,
        "collector": COLLECTOR,
        "collector_status": status,
        "observed_at_epoch": observed_at_epoch,
        "boot_id": boot_id,
        "network_namespace_inode": namespace_inode,
    }
    event.update(fields)
    print(json.dumps(event, separators=(",", ":"), sort_keys=True), flush=True)


observed_at_epoch = int(time.time())
try:
    boot_id = read_text(Path("/proc/sys/kernel/random/boot_id"))
    namespace_inode = os.stat("/proc/self/ns/net").st_ino
    if not boot_id or namespace_inode <= 0:
        raise ValueError("invalid_host_identity")
    bonds = sorted(path for path in SYS_CLASS_NET.iterdir() if (path / "bonding").is_dir())
    if not bonds:
        emit("no_bonds", observed_at_epoch, boot_id, namespace_inode, bond="__none__")
    for bond_path in bonds:
        try:
            bonding = bond_path / "bonding"
            mode_parts = read_text(bonding / "mode").split()
            if len(mode_parts) != 2:
                raise ValueError("invalid_mode")
            slaves = sorted(read_text(bonding / "slaves").split())
            active_slave = read_text(bonding / "active_slave") or "__none__"
            primary = read_text(bonding / "primary") or "__none__"
            event = {
                "bond": bond_path.name,
                "mode_name": mode_parts[0],
                "mode_number": int(mode_parts[1]),
                "active_slave": active_slave,
                "primary": primary,
                "primary_reselect": read_text(bonding / "primary_reselect"),
                "slaves": " ".join(slaves) or "__none__",
                "slave_count": len(slaves),
                "miimon_ms": int(read_text(bonding / "miimon")),
                "arp_interval_ms": int(read_text(bonding / "arp_interval")),
                "bond_operstate": read_optional(bond_path / "operstate"),
                "bond_carrier": read_optional(bond_path / "carrier", int),
            }
            emit("ok", observed_at_epoch, boot_id, namespace_inode, **event)
        except (FileNotFoundError, OSError, UnicodeError, ValueError) as error:
            emit("read_error", observed_at_epoch, boot_id, namespace_inode, bond=bond_path.name, error_type=type(error).__name__)
except (FileNotFoundError, OSError, UnicodeError, ValueError) as error:
    emit("collector_error", observed_at_epoch, None, None, error_type=type(error).__name__)
